function checkpoint(
  record: PantavionDurableExecutionRecord,
  label: string,
  state: Record<string, unknown> = {},
): PantavionDurableExecutionRecord {
  const at = new Date().toISOString();
  return {
    ...record,
    updatedAt: at,
    checkpoints: [
      ...record.checkpoints,
      {
        id: `${record.executionId}:${record.checkpoints.length + 1}`,
        at,
        label,
        state,
      },
    ],
  };
}

